"""
title: Air-Gapped Jupyter Python Executor
description: Execute restricted Python code on a configured local or internal Jupyter server.
version: 1.0.0
"""

from __future__ import annotations

import ast
import json
import os
import time
import uuid
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any, Dict, List, Optional

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover - OpenWebUI normally provides pydantic
    BaseModel = object

    def Field(default=None, description: str = ""):
        return default


class SecurityPolicyError(ValueError):
    pass


class _SecurityVisitor(ast.NodeVisitor):
    DENIED_IMPORT_ROOTS = {
        "os",
        "subprocess",
        "socket",
        "requests",
        "httpx",
        "aiohttp",
        "urllib",
        "http",
        "ftplib",
        "smtplib",
        "paramiko",
        "telnetlib",
        "ssl",
        "shutil",
        "pathlib",
        "glob",
        "importlib",
        "runpy",
        "ctypes",
        "multiprocessing",
        "threading",
        "pickle",
        "marshal",
        "zipfile",
        "tarfile",
    }
    DENIED_CALL_NAMES = {
        "eval",
        "exec",
        "compile",
        "__import__",
        "input",
        "breakpoint",
        "open",
    }
    DENIED_ATTR_NAMES = {
        "system",
        "popen",
        "Popen",
        "run",
        "call",
        "check_call",
        "check_output",
        "remove",
        "unlink",
        "rmtree",
        "rename",
        "replace",
        "chmod",
        "chown",
        "kill",
        "connect",
    }
    FILE_FUNCTION_ATTRS = {
        "read_csv",
        "read_excel",
        "read_json",
        "read_parquet",
        "to_csv",
        "to_excel",
        "to_json",
        "to_parquet",
        "load_workbook",
        "Document",
        "Presentation",
    }

    def __init__(self, allowed_workdir: str):
        self.allowed_workdir = Path(allowed_workdir).resolve() if allowed_workdir else None

    def _fail(self, node: ast.AST, message: str) -> None:
        raise SecurityPolicyError(f"Line {getattr(node, 'lineno', '?')}: {message}")

    def visit_Import(self, node: ast.Import) -> Any:
        for alias in node.names:
            root = alias.name.split(".", 1)[0]
            if root in self.DENIED_IMPORT_ROOTS:
                self._fail(node, f"Import of '{root}' is not allowed by the Jupyter tool policy.")
        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> Any:
        root = (node.module or "").split(".", 1)[0]
        if root in self.DENIED_IMPORT_ROOTS:
            self._fail(node, f"Import from '{root}' is not allowed by the Jupyter tool policy.")
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> Any:
        func = node.func
        if isinstance(func, ast.Name) and func.id in self.DENIED_CALL_NAMES:
            self._fail(node, f"Call to '{func.id}' is not allowed.")
        if isinstance(func, ast.Attribute):
            if func.attr in self.DENIED_ATTR_NAMES:
                self._fail(node, f"Call to attribute '{func.attr}' is not allowed.")
            if func.attr in self.FILE_FUNCTION_ATTRS:
                self._check_path_args(node)
        self.generic_visit(node)

    def _check_path_args(self, node: ast.Call) -> None:
        for arg in list(node.args) + [kw.value for kw in node.keywords]:
            if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                self._check_path_literal(node, arg.value)

    def _check_path_literal(self, node: ast.AST, value: str) -> None:
        parsed = urllib.parse.urlparse(value)
        if parsed.scheme and len(parsed.scheme) > 1:
            self._fail(node, "URLs are not allowed as file paths.")
        if value.startswith("~"):
            self._fail(node, "Home-directory expansion is not allowed.")
        raw_parts = [part for part in re_split_path(value) if part]
        if ".." in raw_parts:
            self._fail(node, "Parent directory traversal is not allowed.")
        path = Path(value)
        if path.is_absolute():
            if not self.allowed_workdir:
                self._fail(node, "Absolute paths require OPENWEBUI_JUPYTER_ALLOWED_WORKDIR.")
            try:
                path.resolve().relative_to(self.allowed_workdir)
            except Exception:
                self._fail(node, "Absolute path is outside OPENWEBUI_JUPYTER_ALLOWED_WORKDIR.")


def re_split_path(value: str) -> List[str]:
    return value.replace("\\", "/").split("/")


def _validate_python_code(code: str, allowed_workdir: str = "") -> None:
    if not isinstance(code, str) or not code.strip():
        raise SecurityPolicyError("Code must be a non-empty Python string.")
    if len(code) > 20000:
        raise SecurityPolicyError("Code is too large for this controlled tool call.")
    for number, line in enumerate(code.splitlines(), start=1):
        stripped = line.lstrip()
        if stripped.startswith("!") or stripped.startswith("%"):
            raise SecurityPolicyError(f"Line {number}: shell and IPython magic commands are not allowed.")
    try:
        tree = ast.parse(code, mode="exec")
    except SyntaxError as exc:
        raise SecurityPolicyError(f"Python syntax error before execution: {exc}") from exc
    _SecurityVisitor(allowed_workdir).visit(tree)


if BaseModel is object:
    class _Valves:
        OPENWEBUI_JUPYTER_URL = ""
        OPENWEBUI_JUPYTER_TOKEN = ""
        OPENWEBUI_JUPYTER_TIMEOUT_SECONDS = 30
        OPENWEBUI_JUPYTER_ALLOWED_WORKDIR = ""
else:
    class _Valves(BaseModel):
        OPENWEBUI_JUPYTER_URL: str = Field(default="", description="Local or internal Jupyter base URL, e.g. http://127.0.0.1:8888")
        OPENWEBUI_JUPYTER_TOKEN: str = Field(default="", description="Jupyter token. Leave empty only for a locally configured tokenless server.")
        OPENWEBUI_JUPYTER_TIMEOUT_SECONDS: int = Field(default=30, description="Execution timeout in seconds.")
        OPENWEBUI_JUPYTER_ALLOWED_WORKDIR: str = Field(default="", description="Allowed working directory on the Jupyter host.")


class _JupyterClient:
    def __init__(self, base_url: str, token: str, timeout_seconds: int):
        self.base_url = base_url.rstrip("/")
        self.token = token or ""
        self.timeout_seconds = max(1, int(timeout_seconds))
        parsed = urllib.parse.urlparse(self.base_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("OPENWEBUI_JUPYTER_URL must be an http(s) URL.")
        self.parsed = parsed

    def _url(self, path: str) -> str:
        query = {}
        if self.token:
            query["token"] = self.token
        suffix = urllib.parse.urlencode(query)
        url = f"{self.base_url}{path}"
        return f"{url}?{suffix}" if suffix else url

    def _headers(self) -> Dict[str, str]:
        headers = {"Content-Type": "application/json"}
        if self.token:
            headers["Authorization"] = f"token {self.token}"
        return headers

    def request(self, method: str, path: str, payload: Optional[dict] = None) -> dict:
        data = None if payload is None else json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(self._url(path), data=data, method=method, headers=self._headers())
        with urllib.request.urlopen(req, timeout=self.timeout_seconds) as response:
            raw = response.read().decode("utf-8")
        return json.loads(raw) if raw else {}

    def execute(self, code: str) -> dict:
        try:
            import websocket  # type: ignore
        except Exception:
            return {
                "ok": False,
                "status": "dependency_missing",
                "error": "Python package 'websocket-client' is required in the OpenWebUI tool runtime to talk to Jupyter channels.",
            }

        kernel_id = ""
        try:
            kernel = self.request("POST", "/api/kernels", {"name": "python3"})
            kernel_id = kernel.get("id", "")
            if not kernel_id:
                raise RuntimeError("Jupyter did not return a kernel id.")
            session_id = uuid.uuid4().hex
            msg_id = uuid.uuid4().hex
            ws_scheme = "wss" if self.parsed.scheme == "https" else "ws"
            qs = {"session_id": session_id}
            if self.token:
                qs["token"] = self.token
            ws_url = f"{ws_scheme}://{self.parsed.netloc}{self.parsed.path.rstrip('/')}/api/kernels/{kernel_id}/channels?{urllib.parse.urlencode(qs)}"
            ws = websocket.create_connection(ws_url, timeout=self.timeout_seconds)
            request = {
                "header": {
                    "msg_id": msg_id,
                    "username": "openwebui",
                    "session": session_id,
                    "date": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "msg_type": "execute_request",
                    "version": "5.3",
                },
                "parent_header": {},
                "metadata": {},
                "content": {
                    "code": code,
                    "silent": False,
                    "store_history": False,
                    "user_expressions": {},
                    "allow_stdin": False,
                    "stop_on_error": True,
                },
                "channel": "shell",
                "buffers": [],
            }
            ws.send(json.dumps(request))
            result = {
                "stdout": "",
                "stderr": "",
                "result": [],
                "display_data": [],
                "error_name": "",
                "error_value": "",
                "traceback": [],
            }
            deadline = time.time() + self.timeout_seconds
            status = "ok"
            while time.time() < deadline:
                raw = ws.recv()
                message = json.loads(raw)
                if message.get("parent_header", {}).get("msg_id") != msg_id:
                    continue
                msg_type = message.get("msg_type") or message.get("header", {}).get("msg_type")
                content = message.get("content", {})
                if msg_type == "stream":
                    if content.get("name") == "stderr":
                        result["stderr"] += content.get("text", "")
                    else:
                        result["stdout"] += content.get("text", "")
                elif msg_type in {"execute_result", "display_data"}:
                    data = content.get("data", {})
                    target = "result" if msg_type == "execute_result" else "display_data"
                    result[target].append(data.get("text/plain") or data)
                elif msg_type == "error":
                    status = "error"
                    result["error_name"] = content.get("ename", "")
                    result["error_value"] = content.get("evalue", "")
                    result["traceback"] = [_sanitize(item, self.token) for item in content.get("traceback", [])]
                elif msg_type == "execute_reply":
                    status = content.get("status", status)
                    break
            else:
                status = "timeout"
                try:
                    self.request("POST", f"/api/kernels/{kernel_id}/interrupt", {})
                except Exception:
                    pass
            try:
                ws.close()
            except Exception:
                pass
            return {"ok": status == "ok", "status": status, "execution": _sanitize_obj(result, self.token)}
        finally:
            if kernel_id:
                try:
                    self.request("DELETE", f"/api/kernels/{kernel_id}")
                except Exception:
                    pass


def _sanitize(text: Any, token: str) -> Any:
    if not isinstance(text, str):
        return text
    if token:
        text = text.replace(token, "<redacted-token>")
    return text


def _sanitize_obj(obj: Any, token: str) -> Any:
    if isinstance(obj, dict):
        return {key: _sanitize_obj(value, token) for key, value in obj.items()}
    if isinstance(obj, list):
        return [_sanitize_obj(value, token) for value in obj]
    return _sanitize(obj, token)


class Tools:
    def __init__(self):
        self.valves = _Valves()

    def run_python(self, code: str, timeout_seconds: Optional[int] = None) -> Dict[str, Any]:
        """
        Execute restricted Python code on a configured Jupyter server and return structured output.

        The static guard blocks common shell, network, import, process and unsafe file operations.
        The real sandbox boundary is still the configured Jupyter server and its operating environment.
        """
        allowed_workdir = self._config("OPENWEBUI_JUPYTER_ALLOWED_WORKDIR")
        try:
            _validate_python_code(code, allowed_workdir)
        except SecurityPolicyError as exc:
            return {"ok": False, "status": "blocked", "error": str(exc)}

        url = self._config("OPENWEBUI_JUPYTER_URL")
        token = self._config("OPENWEBUI_JUPYTER_TOKEN")
        configured_timeout = timeout_seconds or self._config("OPENWEBUI_JUPYTER_TIMEOUT_SECONDS") or 30
        if not url:
            return {"ok": False, "status": "configuration_error", "error": "OPENWEBUI_JUPYTER_URL is not configured."}

        wrapped_code = self._wrap_code(code, allowed_workdir)
        try:
            client = _JupyterClient(url, token, int(configured_timeout))
            response = client.execute(wrapped_code)
        except urllib.error.URLError:
            response = {"ok": False, "status": "connection_error", "error": "Configured Jupyter server is not reachable."}
        except Exception as exc:
            response = {"ok": False, "status": "error", "error": _sanitize(str(exc), token)}
        response["security"] = {
            "static_policy_applied": True,
            "allowed_workdir": allowed_workdir or "not configured",
            "sandbox_boundary": "Actual isolation depends on the configured Jupyter server.",
        }
        return _sanitize_obj(response, token)

    def _config(self, name: str) -> Any:
        value = getattr(self.valves, name, None)
        if value in (None, ""):
            value = os.getenv(name, "")
        return value

    def _wrap_code(self, code: str, allowed_workdir: str) -> str:
        prefix = ""
        if allowed_workdir:
            safe_dir = json.dumps(allowed_workdir)
            prefix = (
                "import os as _openwebui_os\n"
                f"_openwebui_allowed_workdir = {safe_dir}\n"
                "_openwebui_os.makedirs(_openwebui_allowed_workdir, exist_ok=True)\n"
                "_openwebui_os.chdir(_openwebui_allowed_workdir)\n"
                "del _openwebui_os\n"
            )
        return prefix + code

"""
title: Ask User
author: ichrist
version: 1.0
description: Allows the LLM to autonomously trigger 1-5 interactive pop-up questions to gather missing project details.
offline: true
"""
# Air-gap integration note:
# Imported from the public OpenWebUI tool export stored under
# Tools/openwebui_ext/third_party/public_openwebui_tools/.
# This tool only uses OpenWebUI event calls and does not access external
# services. Runtime was adjusted to avoid blocking the async event loop.
from typing import List, Optional
import asyncio


class Tools:
    def __init__(self):
        pass

    async def get_user_clarification(
        self, questions: List[str], __event_call__=None, __event_emitter__=None
    ) -> str:
        """
        Call this tool ONLY when the user's request is too vague or requires specific parameters
        (like website style, target audience, tech stack, or color palette).
        It will present each question in a separate pop-up modal.

        :param questions: A list of 1 to 5 clear, specific questions to ask the user.
        :return: A formatted string containing the user's responses for the LLM to use.
        """
        if not __event_call__:
            return "Error: This environment does not support interactive pop-ups."

        if not questions:
            return "No questions were provided for clarification."

        # Enforce the 1-5 question limit requested
        active_questions = questions[:5]
        collected_data = []

        # Initial status message
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": f"Gathering {len(active_questions)} specific details...",
                        "done": False,
                    },
                }
            )

        for i, q in enumerate(active_questions):
            # Trigger the pop-up modal
            response = await __event_call__(
                {
                    "type": "input",
                    "data": {
                        "title": f"Clarification Step {i+1} of {len(active_questions)}",
                        "message": f"To give you the best result, I need to know:\n\n**{q}**",
                        "placeholder": "Enter your details here...",
                    },
                }
            )

            # Record result (handle empty responses)
            answer = (
                response
                if response and str(response).strip()
                else "[No information provided]"
            )
            collected_data.append(f"Q: {q}\nA: {answer}")

            # Subtle delay for UX smoothness between pop-ups without blocking the event loop.
            await asyncio.sleep(0.3)

        # Final status update
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "All details received! Generating your response...",
                        "done": True,
                    },
                }
            )

        # Return the data to the LLM context
        return "USER CLARIFICATION RECEIVED:\n" + "\n\n".join(collected_data)

"""
title: Offline Artifact Workbench
description: Create offline HTML documents, slide decks, optional PDFs and ZIP bundles in a controlled artifact directory.
version: 1.0.0
license: MIT
security: Writes only below the configured artifact root. Optional PDF conversion uses local allowlisted converters or Python libraries when present. No internet access, arbitrary path reads or shell strings are used.
"""

from __future__ import annotations

import html
import json
import os
import re
import shutil
import subprocess
import zipfile
from pathlib import Path
from typing import Any, Dict, List

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover
    class BaseModel:
        pass

    def Field(default: Any = None, description: str = "") -> Any:
        return default


class Tools:
    """OpenWebUI toolkit for offline artifact creation and handover."""

    class Valves(BaseModel):
        artifact_root: str = Field("/app/backend/data/offline_artifacts", description="Directory where generated artifacts are written.")
        max_html_chars: int = Field(400000, description="Maximum HTML input size.")
        max_zip_files: int = Field(25, description="Maximum files per ZIP bundle.")
        allow_wkhtmltopdf: bool = Field(False, description="Allow local wkhtmltopdf conversion when installed.")

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def create_html_document(self, title: str, body_html: str, filename: str = "document.html", css: str = "", __event_emitter__: Any = None) -> str:
        """
        Create a complete print-ready HTML document in the artifact directory.
        :param title: Document title.
        :param body_html: Trusted HTML body content generated in chat or via Jupyter.
        :param filename: Output HTML filename.
        :param css: Optional additional CSS.
        """
        if len(body_html) > int(self.valves.max_html_chars):
            return "Fehler: HTML-Inhalt ist zu groß."
        await self._emit(__event_emitter__, "Erzeuge HTML-Dokument", False)
        path = self._safe_output_path(filename, ".html")
        document = self._html_shell(title, body_html, css, landscape=False)
        path.write_text(document, encoding="utf-8")
        self._write_manifest(path, "html_document", {"title": title})
        await self._file_event(__event_emitter__, path)
        await self._emit(__event_emitter__, "HTML-Dokument erzeugt", True)
        return self._result("HTML-Dokument", path)

    async def create_slide_deck(self, title: str, slides_json: str, filename: str = "presentation.html", theme_css: str = "", __event_emitter__: Any = None) -> str:
        """
        Create a 16:9 print-ready HTML presentation from JSON slides.
        :param title: Presentation title.
        :param slides_json: JSON array with slide objects containing title, bullets and optional notes.
        :param filename: Output HTML filename.
        :param theme_css: Optional additional CSS.
        """
        if len(slides_json) > int(self.valves.max_html_chars):
            return "Fehler: Slides-JSON ist zu groß."
        await self._emit(__event_emitter__, "Erzeuge HTML-Präsentation", False)
        try:
            slides = json.loads(slides_json)
        except json.JSONDecodeError as exc:
            return f"Fehler: Ungültiges Slides-JSON bei Zeile {exc.lineno}, Spalte {exc.colno}: {exc.msg}"
        if not isinstance(slides, list) or not slides:
            return "Fehler: Slides-JSON muss ein nicht-leeres Array sein."
        safe_slides = [self._normalize_slide(item, idx + 1) for idx, item in enumerate(slides[:80])]
        body = self._slides_body(title, safe_slides)
        path = self._safe_output_path(filename, ".html")
        path.write_text(self._html_shell(title, body, self._slide_css() + "\n" + theme_css, landscape=True), encoding="utf-8")
        self._write_manifest(path, "html_presentation", {"title": title, "slides": len(safe_slides)})
        await self._file_event(__event_emitter__, path)
        await self._emit(__event_emitter__, "HTML-Präsentation erzeugt", True)
        return self._result("HTML-Präsentation", path)

    async def convert_html_to_pdf(self, html_file: str, pdf_filename: str = "", __event_emitter__: Any = None) -> str:
        """
        Convert an existing generated HTML artifact to PDF when a local converter is available.
        :param html_file: HTML artifact path or filename below the artifact root.
        :param pdf_filename: Optional PDF output filename.
        """
        await self._emit(__event_emitter__, "Prüfe PDF-Konverter", False)
        source = self._safe_existing_path(html_file, ".html")
        target = self._safe_output_path(pdf_filename or (source.stem + ".pdf"), ".pdf")
        try:
            converted_by = self._convert_with_weasyprint(source, target)
            if not converted_by and bool(self.valves.allow_wkhtmltopdf):
                converted_by = self._convert_with_wkhtmltopdf(source, target)
        except Exception as exc:
            await self._emit(__event_emitter__, "PDF-Konvertierung fehlgeschlagen", True)
            return f"Fehler: PDF-Konvertierung fehlgeschlagen: {type(exc).__name__}: {self._redact(str(exc))}"
        if not converted_by:
            return "Fehler: Kein lokaler PDF-Konverter verfügbar. Installiere lokal `weasyprint` im OpenWebUI-Container oder aktiviere ein installiertes `wkhtmltopdf` über die Tool-Valve."
        self._write_manifest(target, "pdf", {"source": str(source.name), "converter": converted_by})
        await self._file_event(__event_emitter__, target)
        await self._emit(__event_emitter__, "PDF erzeugt", True)
        return self._result(f"PDF ({converted_by})", target)

    async def bundle_artifacts(self, artifact_files_json: str, zip_filename: str = "artifacts.zip", __event_emitter__: Any = None) -> str:
        """
        Bundle generated artifacts into a ZIP archive.
        :param artifact_files_json: JSON array of artifact filenames or paths below the artifact root.
        :param zip_filename: Output ZIP filename.
        """
        await self._emit(__event_emitter__, "Erzeuge ZIP-Paket", False)
        try:
            items = json.loads(artifact_files_json)
        except json.JSONDecodeError as exc:
            return f"Fehler: Ungültiges JSON bei Zeile {exc.lineno}, Spalte {exc.colno}: {exc.msg}"
        if not isinstance(items, list) or len(items) > int(self.valves.max_zip_files):
            return "Fehler: Erwartet wird ein JSON-Array innerhalb der konfigurierten Dateigrenze."
        target = self._safe_output_path(zip_filename, ".zip")
        with zipfile.ZipFile(target, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for item in items:
                source = self._safe_existing_path(str(item), "")
                archive.write(source, arcname=source.name)
        self._write_manifest(target, "zip_bundle", {"files": len(items)})
        await self._file_event(__event_emitter__, target)
        await self._emit(__event_emitter__, "ZIP-Paket erzeugt", True)
        return self._result("ZIP-Paket", target)

    def _root(self) -> Path:
        root = Path(os.environ.get("OPENWEBUI_ARTIFACT_ROOT", str(self.valves.artifact_root))).expanduser().resolve()
        root.mkdir(parents=True, exist_ok=True)
        return root

    def _safe_output_path(self, filename: str, suffix: str) -> Path:
        name = Path(filename or f"artifact{suffix}").name
        name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name).strip(" .") or f"artifact{suffix}"
        if not name.lower().endswith(suffix):
            name += suffix
        path = (self._root() / name).resolve()
        if self._root() not in path.parents and path != self._root():
            raise ValueError("Ausgabepfad liegt außerhalb des Artefaktverzeichnisses.")
        return path

    def _safe_existing_path(self, file_name: str, suffix: str) -> Path:
        candidate = Path(file_name)
        path = (candidate if candidate.is_absolute() else self._root() / candidate.name).resolve()
        if self._root() not in path.parents:
            raise ValueError("Datei liegt außerhalb des Artefaktverzeichnisses.")
        if suffix and path.suffix.lower() != suffix:
            raise ValueError(f"Erwartet wird eine `{suffix}`-Datei.")
        if not path.exists() or not path.is_file():
            raise ValueError("Artefaktdatei wurde nicht gefunden.")
        return path

    def _html_shell(self, title: str, body: str, css: str, landscape: bool) -> str:
        page = "A4 landscape" if landscape else "A4"
        base_css = f"""
@page {{ size: {page}; margin: 14mm; }}
* {{ box-sizing: border-box; }}
body {{ margin: 0; font-family: Arial, Helvetica, sans-serif; color: #111827; background: #ffffff; line-height: 1.45; }}
h1, h2, h3 {{ page-break-after: avoid; }}
img, table, pre {{ max-width: 100%; }}
section {{ break-inside: avoid; }}
"""
        return "<!doctype html>\n<html lang=\"de\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n" + f"<title>{html.escape(title)}</title>\n<style>\n{base_css}\n{css}\n</style>\n</head>\n<body>\n{body}\n</body>\n</html>\n"

    def _slide_css(self) -> str:
        return """
@page { size: 297mm 167.0625mm; margin: 0; }
body { background: #f8fafc; }
.slide { width: 297mm; min-height: 167.0625mm; padding: 18mm 22mm; page-break-after: always; background: #ffffff; display: flex; flex-direction: column; justify-content: center; }
.slide h1 { font-size: 34pt; margin: 0 0 10mm; }
.slide h2 { font-size: 26pt; margin: 0 0 8mm; }
.slide ul { font-size: 17pt; margin: 0; padding-left: 9mm; }
.slide li { margin: 0 0 4mm; }
.slide .notes { margin-top: 10mm; font-size: 10pt; color: #475569; }
"""

    def _slides_body(self, title: str, slides: List[Dict[str, Any]]) -> str:
        parts = [f"<section class=\"slide\"><h1>{html.escape(title)}</h1><p>Offline erzeugte HTML-Präsentation</p></section>"]
        for slide in slides:
            bullets = "".join(f"<li>{html.escape(item)}</li>" for item in slide["bullets"])
            notes = f"<p class=\"notes\">{html.escape(slide['notes'])}</p>" if slide["notes"] else ""
            parts.append(f"<section class=\"slide\"><h2>{html.escape(slide['title'])}</h2><ul>{bullets}</ul>{notes}</section>")
        return "\n".join(parts)

    def _normalize_slide(self, item: Any, index: int) -> Dict[str, Any]:
        if not isinstance(item, dict):
            return {"title": f"Folie {index}", "bullets": [str(item)[:300]], "notes": ""}
        title = str(item.get("title") or f"Folie {index}")[:180]
        raw_bullets = item.get("bullets") or item.get("points") or []
        if isinstance(raw_bullets, str):
            raw_bullets = [raw_bullets]
        bullets = [str(point)[:300] for point in list(raw_bullets)[:8]] or ["Inhalt ergänzen"]
        notes = str(item.get("notes") or "")[:1000]
        return {"title": title, "bullets": bullets, "notes": notes}

    def _convert_with_weasyprint(self, source: Path, target: Path) -> str:
        try:
            from weasyprint import HTML  # type: ignore
        except Exception:
            return ""
        HTML(filename=str(source)).write_pdf(str(target))
        return "weasyprint"

    def _convert_with_wkhtmltopdf(self, source: Path, target: Path) -> str:
        exe = shutil.which("wkhtmltopdf")
        if not exe:
            return ""
        subprocess.run([exe, "--disable-local-file-access", str(source), str(target)], check=True, timeout=60)
        return "wkhtmltopdf"

    def _write_manifest(self, path: Path, artifact_type: str, meta: Dict[str, Any]) -> None:
        manifest = {"artifact": path.name, "type": artifact_type, "meta": meta}
        path.with_suffix(path.suffix + ".manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")

    def _result(self, label: str, path: Path) -> str:
        return "\n".join(["# Artefakt erzeugt", f"- Typ: {label}", f"- Datei: `{path}`", f"- Größe: {path.stat().st_size} Bytes", "", "Hinweis: Für direkte Downloads muss das Artefaktverzeichnis in der OpenWebUI-Instanz als erreichbarer Datei-/Volume-Pfad eingebunden sein."])

    def _redact(self, value: str) -> str:
        return re.sub(r"(?i)(token|api[_-]?key|password|secret)=([^&\s]+)", r"\1=[REDACTED]", value)

    async def _emit(self, emitter: Any, description: str, done: bool) -> None:
        if emitter:
            await emitter({"type": "status", "data": {"description": description, "done": done}})

    async def _file_event(self, emitter: Any, path: Path) -> None:
        if emitter:
            await emitter({"type": "chat:message:files", "data": {"files": [{"name": path.name, "path": str(path)}]}})

"""
title: OpenAPI Schema Inspector
description: Analyze pasted OpenAPI JSON and summarize endpoints, parameters and security hints without making API calls.
version: 1.0.0
license: MIT
security: This tool parses user-provided text only. It does not call APIs, process tokens, access files or execute shell commands.
"""

from __future__ import annotations

import json
import re
from typing import Any, Dict, List

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover
    class BaseModel:
        pass

    def Field(default: Any = None, description: str = "") -> Any:
        return default


HTTP_METHODS = {"get", "post", "put", "patch", "delete", "head", "options", "trace"}


class Tools:
    """OpenWebUI toolkit for local OpenAPI schema review."""

    class Valves(BaseModel):
        max_input_chars: int = Field(250000, description="Maximum OpenAPI text length.")
        max_endpoints: int = Field(80, description="Maximum endpoints included in the result.")

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def inspect_openapi_json(self, schema_json: str, __event_emitter__: Any = None) -> str:
        """
        Inspect an OpenAPI JSON schema supplied as text.
        :param schema_json: JSON document containing an OpenAPI 3.x or Swagger 2.0 schema.
        """
        if len(schema_json) > int(self.valves.max_input_chars):
            return "Fehler: Schema ist zu groß für die konfigurierte Analysegrenze."
        await self._emit(__event_emitter__, "Analysiere OpenAPI-Schema", False)
        try:
            schema = json.loads(schema_json)
        except json.JSONDecodeError as exc:
            return f"Fehler: Ungültiges JSON bei Zeile {exc.lineno}, Spalte {exc.colno}: {exc.msg}"
        if not isinstance(schema, dict):
            return "Fehler: Das OpenAPI-Schema muss ein JSON-Objekt sein."

        title = self._text(schema.get("info", {}).get("title", "Unbenannt"))
        version = self._text(schema.get("info", {}).get("version", "unbekannt"))
        paths = schema.get("paths", {})
        security_schemes = schema.get("components", {}).get("securitySchemes", {}) or schema.get("securityDefinitions", {})
        endpoints = self._collect_endpoints(paths)
        risks = self._risks(schema, endpoints, security_schemes)
        await self._emit(__event_emitter__, "OpenAPI-Analyse abgeschlossen", True)

        lines = [
            "# OpenAPI-Analyse",
            f"- Titel: {title}",
            f"- Version: {version}",
            f"- OpenAPI/Swagger: {self._text(schema.get('openapi', schema.get('swagger', 'nicht angegeben')))}",
            f"- Endpunkte erkannt: {len(endpoints)}",
            f"- Security-Schemes: {', '.join(security_schemes.keys()) if security_schemes else 'keine'}",
            "",
            "## Endpunkte",
        ]
        for endpoint in endpoints[: int(self.valves.max_endpoints)]:
            lines.append(f"- `{endpoint['method'].upper()} {endpoint['path']}`: {endpoint['summary']}")
            if endpoint["params"]:
                lines.append(f"  Parameter: {', '.join(endpoint['params'][:12])}")
            if endpoint["auth"]:
                lines.append(f"  Auth-Hinweis: {endpoint['auth']}")
        if len(endpoints) > int(self.valves.max_endpoints):
            lines.append(f"- ... {len(endpoints) - int(self.valves.max_endpoints)} weitere Endpunkte gekürzt")
        lines.extend(["", "## Risiken und Lücken"])
        lines.extend(f"- {risk}" for risk in risks) if risks else lines.append("- Keine offensichtlichen strukturellen Risiken erkannt.")
        lines.extend(["", "## Tooling-Empfehlung", "- Erst nur lesende Endpunkte anbinden.", "- Authentifizierung über Valves oder OAuth-Injektion konfigurieren; Tokens nie in Prompts oder Logs ausgeben.", "- Für schreibende Endpunkte explizite Bestätigung, Eingabevalidierung und Audit-Logging vorsehen."])
        return "\n".join(lines)

    def _collect_endpoints(self, paths: Any) -> List[Dict[str, Any]]:
        endpoints: List[Dict[str, Any]] = []
        if not isinstance(paths, dict):
            return endpoints
        for path, operations in paths.items():
            if not isinstance(operations, dict):
                continue
            for method, operation in operations.items():
                if method.lower() not in HTTP_METHODS or not isinstance(operation, dict):
                    continue
                params = []
                for param in operation.get("parameters", []):
                    if isinstance(param, dict):
                        params.append(self._text(param.get("name", "unnamed")) + ":" + self._text(param.get("in", "unknown")))
                auth = "operation security gesetzt" if operation.get("security") else ""
                endpoints.append({"path": self._text(path), "method": method, "summary": self._text(operation.get("summary") or operation.get("operationId") or "ohne Kurzbeschreibung"), "params": params, "auth": auth})
        return endpoints

    def _risks(self, schema: Dict[str, Any], endpoints: List[Dict[str, Any]], security_schemes: Dict[str, Any]) -> List[str]:
        risks: List[str] = []
        if not schema.get("servers") and not schema.get("host"):
            risks.append("Keine Server- oder Host-Angabe vorhanden.")
        if not security_schemes:
            risks.append("Keine zentralen Security-Schemes definiert.")
        for endpoint in endpoints:
            if endpoint["method"].lower() in {"post", "put", "patch", "delete"} and not endpoint["auth"]:
                risks.append(f"Schreibender Endpunkt ohne operationale Security-Angabe: {endpoint['method'].upper()} {endpoint['path']}")
        if any(re.search(r"(token|password|secret|api[_-]?key)", p, re.I) for e in endpoints for p in e["params"]):
            risks.append("Parameter mit potentiell sensiblen Namen erkannt; Ausgabe und Logging redigieren.")
        return risks[:25]

    def _text(self, value: Any) -> str:
        return str(value).replace("\n", " ").strip()[:300]

    async def _emit(self, emitter: Any, description: str, done: bool) -> None:
        if emitter:
            await emitter({"type": "status", "data": {"description": description, "done": done}})

