def _build_openui_html(code: str, title: str = "Response", cdn_base: str = _CDN_BASE) -> str:
    safe_title = (
        title.replace("&", "&amp;").replace("<", "&lt;")
        .replace(">", "&gt;").replace('"', "&quot;")
    )
    code_json = json.dumps(code)
    return f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{safe_title}</title>
<meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data: blob:; font-src 'self' data:; object-src 'none'; base-uri 'self'">
<link rel="stylesheet" href="{cdn_base}/dist/openui-styles.css">
<style>
* {{ box-sizing: border-box; margin: 0; }}
html, body {{ background: transparent; }}
body {{ padding: 4px; overflow: visible; }}
#openui-root {{ width: 100%; }}
.openui-loading {{
  display: flex; align-items: center; justify-content: center;
  padding: 32px; color: #888; font-family: system-ui, -apple-system, sans-serif;
  font-size: 14px;
}}
.openui-error {{
  padding: 16px; color: #dc2626; font-family: system-ui, sans-serif;
  background: #fef2f2; border-radius: 8px; border: 1px solid #fecaca;
  font-size: 13px; line-height: 1.5;
}}
.openui-error strong {{ display: block; margin-bottom: 4px; }}
</style>
{_THEME_SCRIPT}
</head>
<body>
<div id="openui-root"><div class="openui-loading">Loading components&#8230;</div></div>
{_BODY_SCRIPTS}
<script>
(function() {{
  var script = document.createElement('script');
  script.src = '{cdn_base}/dist/openui-bundle.min.js';
  script.onload = function() {{
    try {{
      var OpenUI = window.__OpenUI;
      if (!OpenUI || !OpenUI.Renderer || !OpenUI.openuiChatLibrary) {{
        throw new Error('OpenUI bundle loaded but exports missing');
      }}
      var code = {code_json};
      var container = document.getElementById('openui-root');
      container.innerHTML = '';
      var root = OpenUI.createRoot(container);
      function handleAction(event) {{
        if (event.type === 'open_url') {{
          openLink(event.params && event.params.url ? event.params.url : '');
          return;
        }}
        var prompt = event.humanFriendlyMessage || (event.params && event.params.message) || '';
        if (event.formState && Object.keys(event.formState).length > 0) {{
          var formDataStr = Object.entries(event.formState)
            .map(function(entry) {{ return entry[0] + ': ' + JSON.stringify(entry[1]); }})
            .join('\\n');
          prompt = prompt
            ? prompt + '\\n\\nForm data:\\n' + formDataStr
            : 'Form submission' + (event.formName ? ' (' + event.formName + ')' : '') + ':\\n' + formDataStr;
        }}
        if (!prompt && event.type) {{
          prompt = 'User action: ' + event.type + (event.params ? '\\n' + JSON.stringify(event.params) : '');
        }}
        if (prompt) {{
          sendPrompt(prompt);
        }}
      }}
      root.render(OpenUI.React.createElement(OpenUI.Renderer, {{
        response: code,
        library: OpenUI.openuiChatLibrary,
        isStreaming: false,
        onAction: handleAction
      }}));
      setTimeout(reportHeight, 500);
      setTimeout(reportHeight, 2000);
    }} catch(err) {{
      var el = document.getElementById('openui-root');
      el.innerHTML = '<div class="openui-error"><strong>Failed to render OpenUI</strong>'
        + (err.message || String(err)).replace(/</g, '&lt;') + '</div>';
      console.error('OpenUI render error:', err);
      reportHeight();
    }}
  }};
  script.onerror = function() {{
    var el = document.getElementById('openui-root');
    el.innerHTML = '<div class="openui-error"><strong>Failed to load OpenUI bundle</strong>'
      + 'Could not load ' + script.src + '. In Air-Gap-Betrieb muss das OpenUI-Bundle lokal unter /static/openui/dist bereitgestellt werden.</div>';
    reportHeight();
  }};
  document.body.appendChild(script);
}})();
</script>
</body>
</html>"""
# ---------------------------------------------------------------------------
# Tool class
# ---------------------------------------------------------------------------
class Tools:
    """OpenUI Generative UI - renders interactive components in chat.
    When the user's question could benefit from a visual response (charts,
    tables, forms, cards, step lists, follow-ups, etc.), call render_openui
    to render a rich interactive UI instead of plain markdown.
    NEVER output openui-lang code as text. ALWAYS pass it to render_openui.
    """
    class Valves(BaseModel):
        cdn_base_url: str = Field(
            default=_CDN_BASE,
            description="Local OpenUI bundle base path. Air-gap default expects openui-bundle.min.js and openui-styles.css under /static/openui/dist.",
        )
    def __init__(self):
        self.valves = self.Valves()
    async def render_openui(
        self,
        openui_lang_code: str,
        title: str = "Response",
        __event_emitter__=None,
    ) -> tuple:
        """
        Render interactive UI components inline in the chat using OpenUI Lang.
        Use this tool whenever a visual response would be helpful: tables, charts,
        forms, lists, cards, step guides, follow-up suggestions, etc.
        IMPORTANT: Pass the openui-lang code as the openui_lang_code argument.
        NEVER output openui-lang as text in your response. After calling this tool,
        briefly describe what the user sees - do NOT echo the source code.
        ## OpenUI Lang Syntax
        Each statement: `identifier = Expression`. `root = Card(...)` is the entry point.
        Expressions: strings ("..."), numbers, booleans, null, arrays ([...]), objects ({...}), or TypeName(arg1, arg2, ...).
        Arguments are POSITIONAL. Write TypeName(arg1, arg2) NOT TypeName(key: val).
        Every variable (except root) must be referenced by another. Unreferenced = not rendered.
        ## Components
        Card(children[]) - root container, children stack vertically.
        CardHeader(title?, subtitle?)
        TextContent(text, size?) - size: "small"|"default"|"large"|"small-heavy"|"large-heavy"
        MarkDownRenderer(textMarkdown, variant?) - variant: "clear"|"card"|"sunk"
        Callout(variant, title, description) - variant: "info"|"warning"|"error"|"success"|"neutral"
        TextCallout(variant?, title?, description?)
        Image(alt, src?)
        ImageBlock(src, alt?)
        ImageGallery(images[{src,alt?,details?}])
        CodeBlock(language, codeString)
        Separator(orientation?, decorative?)
        Table(columns: Col[])
        Col(label, data[], type?) - type: "string"|"number"|"action"
        BarChart(labels[], series: Series[], variant?, xLabel?, yLabel?) - variant: "grouped"|"stacked"
        LineChart(labels[], series: Series[], variant?, xLabel?, yLabel?) - variant: "linear"|"natural"|"step"
        AreaChart(labels[], series: Series[], variant?, xLabel?, yLabel?)
        HorizontalBarChart(labels[], series: Series[], variant?, xLabel?, yLabel?)
        RadarChart(labels[], series: Series[])
        Series(category, values[])
        PieChart(labels[], values[], variant?) - variant: "pie"|"donut"
        RadialChart(labels[], values[])
        SingleStackedBarChart(labels[], values[])
        ScatterChart(datasets: ScatterSeries[], xLabel?, yLabel?)
        ScatterSeries(name, points: Point[])
        Point(x, y, z?)
        Form(name, buttons: Buttons, fields?: FormControl[])
        FormControl(label, input, hint?)
        Input(name, placeholder?, type?, rules?, value?)
        TextArea(name, placeholder?, rows?, rules?, value?)
        Select(name, items: SelectItem[], placeholder?, rules?, value?)
        SelectItem(value, label)
        DatePicker(name, mode?, rules?, value?)
        Slider(name, variant, min, max, step?, defaultValue?, label?, rules?, value?)
        CheckBoxGroup(name, items: CheckBoxItem[], rules?, value?)
        CheckBoxItem(label, description, name, defaultChecked?)
        RadioGroup(name, items: RadioItem[], defaultValue?, rules?, value?)
        RadioItem(label, description, value)
        SwitchGroup(name, items: SwitchItem[], variant?, value?)
        SwitchItem(label?, description?, name, defaultChecked?)
        Button(label, action?, variant?, type?, size?) - variant: "primary"|"secondary"|"tertiary"
        Buttons(buttons[], direction?) - direction: "row"|"column"
        ListBlock(items: ListItem[], variant?) - variant: "number"|"image"
        ListItem(title, subtitle?, image?, actionLabel?, action?)
        FollowUpBlock(items: FollowUpItem[]) - clickable follow-ups at end
        FollowUpItem(text) - clicking sends text as user message
        SectionBlock(sections: SectionItem[], isFoldable?)
        SectionItem(value, trigger, content[])
        Tabs(items: TabItem[])
        TabItem(value, trigger, content[])
        Accordion(items: AccordionItem[])
        AccordionItem(value, trigger, content[])
        Steps(items: StepsItem[])
        StepsItem(title, details)
        Carousel(children[][], variant?) - each slide is array of components; all slides same structure
        TagBlock(tags[])
        Tag(text, icon?, size?, variant?)
        Action([@steps...]) - wires buttons. Steps: @ToAssistant("msg"), @OpenUrl("url")
        Buttons without Action auto-send their label.
        ## Examples
        Table: root = Card([title, tbl, followUps])
        title = TextContent("Top Languages", "large-heavy")
        tbl = Table([Col("Language", langs), Col("Users (M)", users)])
        langs = ["Python", "JavaScript", "Java"]
        users = [15.7, 14.2, 12.1]
        followUps = FollowUpBlock([FollowUpItem("Tell me more about Python")])
        Chart: root = Card([header, chart])
        header = CardHeader("Monthly Revenue")
        chart = BarChart(months, [Series("Revenue", values)])
        months = ["Jan", "Feb", "Mar", "Apr"]
        values = [42000, 51000, 48000, 62000]
        Form: root = Card([title, form])
        title = TextContent("Contact Us", "large-heavy")
        form = Form("contact", btns, [nameField, emailField])
        nameField = FormControl("Name", Input("name", "Your name", "text", {required: true}))
        emailField = FormControl("Email", Input("email", "you@example.com", "email", {required: true, email: true}))
        btns = Buttons([Button("Submit", Action([@ToAssistant("Submit")]), "primary")])
        ## Rules
        - root = Card(...) MUST be the FIRST line.
        - Every name must be defined and reachable from root.
        - Card is the only layout container. Do NOT use Stack.
        - Use FollowUpBlock at the END for next actions.
        - Carousel slides MUST all have the same structure.
        - Generate realistic data when asked about data.
        :param openui_lang_code: Complete OpenUI Lang code starting with root = Card(...)
        :param title: Short descriptive title for the rendered UI.
        :return: Interactive rich embed rendered inline in the chat.
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": f"Rendering \"{title}\"...",
                        "done": False,
                    },
                }
            )
        response = HTMLResponse(
            content=_build_openui_html(openui_lang_code, title, self.valves.cdn_base_url),
            headers={"Content-Disposition": "inline"},
        )
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": f"Rendered \"{title}\"",
                        "done": True,
                    },
                }
            )
        result_context = (
            f'OpenUI visualization "{title}" is now rendered and visible to the '
            f"user as an interactive embed. DO NOT echo back the OpenUI Lang source "
            f"code. Instead, briefly describe what the visualization shows in plain "
            f"language. If the visualization has interactive elements (clickable items, "
            f"buttons, forms, follow-ups), mention what the user can interact with."
        )
        return response, result_context

"""
title: Offline Parallel Task Planner
description: Split work into dependency-safe parallel waves and subagent assignments without executing external tools.
version: 1.0.0
license: MIT
security: Processes supplied JSON/text only. It does not call models, tools, networks, files or shell commands.
"""

from __future__ import annotations

import json
import re
from typing import Any, Dict, List, Set

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover
    class BaseModel:
        pass

    def Field(default: Any = None, description: str = "") -> Any:
        return default


class Tools:
    """OpenWebUI toolkit for conservative parallel-work planning."""

    class Valves(BaseModel):
        max_input_chars: int = Field(180000, description="Maximum JSON/text input size.")
        max_tasks: int = Field(120, description="Maximum tasks per plan.")
        default_timeout_minutes: int = Field(20, description="Default timeout for a delegated task.")

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def build_parallel_execution_plan(self, goal: str, tasks_json: str, __event_emitter__: Any = None) -> str:
        """
        Build dependency-safe execution waves from task JSON.
        :param goal: Overall objective.
        :param tasks_json: JSON array with id, title, depends_on, tool, subagent, risk fields.
        """
        if len(tasks_json) > int(self.valves.max_input_chars):
            return "Fehler: Eingabe ist zu groß."
        await self._emit(__event_emitter__, "Berechne parallele Ausführungswellen", False)
        try:
            tasks = self._parse_tasks(tasks_json)
            waves = self._waves(tasks)
        except ValueError as exc:
            return f"Fehler: {exc}"
        lines = ["# Parallelplan", f"- Ziel: {self._clean(goal, 500)}", f"- Aufgaben: {len(tasks)}", f"- Wellen: {len(waves)}", ""]
        for wave_index, wave in enumerate(waves, 1):
            lines.append(f"## Welle {wave_index}")
            for task_id in wave:
                task = tasks[task_id]
                actor = task.get("subagent") or task.get("tool") or "Hauptmodell"
                risk = task.get("risk") or "normal"
                lines.append(f"- `{task_id}` {task['title']} | Akteur: {actor} | Risiko: {risk}")
            lines.append("")
        lines.extend(self._safety_notes(tasks))
        await self._emit(__event_emitter__, "Parallelplan erzeugt", True)
        return "\n".join(lines).strip()

    async def split_for_subagents(self, goal: str, workstreams_json: str, subagent_profiles_json: str = "[]", __event_emitter__: Any = None) -> str:
        """
        Assign workstreams to subagent profiles by declared capability keywords.
        :param goal: Overall objective.
        :param workstreams_json: JSON array with title, capabilities and deliverable fields.
        :param subagent_profiles_json: JSON array with name, capabilities, tools and limits fields.
        """
        if len(workstreams_json) + len(subagent_profiles_json) > int(self.valves.max_input_chars):
            return "Fehler: Eingabe ist zu groß."
        await self._emit(__event_emitter__, "Ordne Subagenten zu", False)
        streams = self._load_array(workstreams_json, "workstreams_json")
        profiles = self._load_array(subagent_profiles_json, "subagent_profiles_json") if subagent_profiles_json.strip() else []
        if isinstance(streams, str):
            return streams
        if isinstance(profiles, str):
            return profiles
        lines = ["# Subagent-Aufteilung", f"- Ziel: {self._clean(goal, 500)}", ""]
        for index, stream in enumerate(streams[: int(self.valves.max_tasks)], 1):
            needed = self._keywords(stream.get("capabilities", stream.get("skills", "")) if isinstance(stream, dict) else "")
            best = self._best_profile(needed, profiles)
            title = self._clean(str(stream.get("title") or f"Arbeitsstrom {index}") if isinstance(stream, dict) else str(stream), 120)
            deliverable = self._clean(str(stream.get("deliverable") or "kurzes Ergebnis mit Annahmen und offenen Punkten") if isinstance(stream, dict) else "kurzes Ergebnis", 220)
            lines.append(f"## {title}")
            lines.append(f"- Subagent/Modell: {best}")
            lines.append(f"- Ergebnis: {deliverable}")
            lines.append(f"- Timeout: {int(self.valves.default_timeout_minutes)} Minuten")
            lines.append("- Regel: nur unabhängige Arbeit parallelisieren; abhängige Aufgaben in spätere Wellen legen.")
            lines.append("")
        await self._emit(__event_emitter__, "Subagent-Aufteilung erzeugt", True)
        return "\n".join(lines).strip()

    async def merge_parallel_results(self, results_json: str, __event_emitter__: Any = None) -> str:
        """
        Merge parallel worker/subagent result summaries into one handover.
        :param results_json: JSON array with source, status, summary, changed_files, risks and next_steps fields.
        """
        if len(results_json) > int(self.valves.max_input_chars):
            return "Fehler: Eingabe ist zu groß."
        await self._emit(__event_emitter__, "Konsolidiere parallele Ergebnisse", False)
        results = self._load_array(results_json, "results_json")
        if isinstance(results, str):
            return results
        lines = ["# Konsolidiertes Ergebnis", ""]
        statuses: Dict[str, int] = {}
        for item in results[: int(self.valves.max_tasks)]:
            status = self._clean(str(item.get("status", "unknown")) if isinstance(item, dict) else "unknown", 30)
            statuses[status] = statuses.get(status, 0) + 1
        lines.append("## Status")
        lines.extend(f"- {key}: {value}" for key, value in sorted(statuses.items()))
        lines.append("")
        lines.append("## Beiträge")
        for item in results[: int(self.valves.max_tasks)]:
            if not isinstance(item, dict):
                lines.append(f"- {self._clean(str(item), 240)}")
                continue
            source = self._clean(str(item.get("source") or item.get("agent") or "Quelle"), 80)
            summary = self._clean(str(item.get("summary") or item.get("result") or ""), 500)
            risks = self._join_list(item.get("risks", []))
            files = self._join_list(item.get("changed_files", []))
            lines.append(f"- `{source}`: {summary}")
            if files:
                lines.append(f"  Dateien: {files}")
            if risks:
                lines.append(f"  Risiken: {risks}")
        await self._emit(__event_emitter__, "Ergebnisse konsolidiert", True)
        return "\n".join(lines)

    def _parse_tasks(self, text: str) -> Dict[str, Dict[str, Any]]:
        raw = self._load_array(text, "tasks_json")
        if isinstance(raw, str):
            raise ValueError(raw.replace("Fehler: ", "", 1))
        tasks: Dict[str, Dict[str, Any]] = {}
        for index, item in enumerate(raw[: int(self.valves.max_tasks)], 1):
            if not isinstance(item, dict):
                item = {"title": str(item)}
            task_id = self._task_id(str(item.get("id") or f"task-{index}"))
            depends = item.get("depends_on", item.get("dependencies", []))
            if isinstance(depends, str):
                depends = [part.strip() for part in depends.split(",") if part.strip()]
            if not isinstance(depends, list):
                depends = []
            tasks[task_id] = {
                "id": task_id,
                "title": self._clean(str(item.get("title") or item.get("task") or task_id), 160),
                "depends_on": [self._task_id(str(dep)) for dep in depends],
                "tool": self._clean(str(item.get("tool") or ""), 80),
                "subagent": self._clean(str(item.get("subagent") or item.get("agent") or ""), 80),
                "risk": self._clean(str(item.get("risk") or ""), 40),
            }
        unknown = sorted({dep for task in tasks.values() for dep in task["depends_on"] if dep not in tasks})
        if unknown:
            raise ValueError(f"Unbekannte Abhängigkeiten: {', '.join(unknown)}")
        return tasks

    def _waves(self, tasks: Dict[str, Dict[str, Any]]) -> List[List[str]]:
        pending: Set[str] = set(tasks)
        done: Set[str] = set()
        waves: List[List[str]] = []
        while pending:
            ready = sorted(task_id for task_id in pending if set(tasks[task_id]["depends_on"]).issubset(done))
            if not ready:
                cycle = ", ".join(sorted(pending))
                raise ValueError(f"Zyklische oder blockierende Abhängigkeiten erkannt: {cycle}")
            waves.append(ready)
            done.update(ready)
            pending.difference_update(ready)
        return waves

    def _safety_notes(self, tasks: Dict[str, Dict[str, Any]]) -> List[str]:
        stateful = [task["id"] for task in tasks.values() if re.search(r"(?i)(write|delete|deploy|commit|push|datei|shell|docker)", task.get("tool", "") + " " + task["title"])]
        lines = ["## Sicherheitsregeln", "- Gemeinsame Schreibziele nicht parallel ausführen.", "- Netzwerk-, Shell- und Dateischreib-Tools mit Timeout und klarem Besitzer ausführen."]
        if stateful:
            lines.append(f"- Sequenziell prüfen wegen möglichem Zustand/Schreibzugriff: {', '.join(stateful)}")
        return lines

    def _load_array(self, text: str, label: str) -> List[Any] | str:
        try:
            data = json.loads(text or "[]")
        except json.JSONDecodeError as exc:
            return f"Fehler: {label} ist ungültiges JSON bei Zeile {exc.lineno}, Spalte {exc.colno}: {exc.msg}"
        if not isinstance(data, list):
            return f"Fehler: {label} muss ein JSON-Array sein."
        return data

    def _best_profile(self, needed: Set[str], profiles: List[Any]) -> str:
        best_name, best_score = "Standard-Subagent", -1
        for profile in profiles:
            if not isinstance(profile, dict):
                continue
            caps = self._keywords(profile.get("capabilities", profile.get("skills", "")))
            score = len(needed.intersection(caps))
            if score > best_score:
                best_name = self._clean(str(profile.get("name") or profile.get("model") or "Subagent"), 80)
                best_score = score
        return best_name

    def _keywords(self, value: Any) -> Set[str]:
        if isinstance(value, list):
            value = " ".join(str(item) for item in value)
        return {part.lower() for part in re.findall(r"[A-Za-zÄÖÜäöüß0-9_-]{3,}", str(value))}

    def _task_id(self, value: str) -> str:
        return re.sub(r"[^a-zA-Z0-9_-]+", "-", value.strip().lower()).strip("-")[:60] or "task"

    def _join_list(self, value: Any) -> str:
        if not isinstance(value, list):
            value = [value] if value else []
        return ", ".join(self._clean(str(item), 120) for item in value if str(item).strip())

    def _clean(self, value: str, limit: int) -> str:
        return re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]+", " ", value).strip()[:limit]

    async def _emit(self, emitter: Any, description: str, done: bool) -> None:
        if emitter:
            await emitter({"type": "status", "data": {"description": description, "done": done}})

"""
title: Parallel Tools
author: skyzi000
version: 0.1.12
license: MIT
required_open_webui_version: 0.7.0
description: Execute multiple independent tool calls in parallel for faster results.

Open WebUI executes tool calls sequentially, which can be slow when multiple
independent tools need to run. This tool allows you to batch independent tool
calls and execute them concurrently using asyncio.gather.

Limitations:
- Requires a high-capability model (e.g., GPT-5.2, Claude Opus 4.6) to correctly
  invoke this tool. Smaller/mid-tier models may fail to pass the tool_calls
  parameter in the expected format.
offline: true
"""
# Air-gap integration note:
# Imported from the public OpenWebUI tool export stored under
# Tools/openwebui_ext/third_party/public_openwebui_tools/.
# Defaults were adjusted for offline operation: no public API fallback, no
# external CDN by default, and no public web crawling/search unless an admin
# explicitly configures local/self-hosted endpoints and allowlists.
import asyncio
import ast
import json
import logging
import uuid
from typing import Any, Callable, List, Optional

from fastapi import Request
from pydantic import BaseModel, Field

log = logging.getLogger(__name__)


class ToolCallItem(BaseModel):
    """A single tool call specification."""

    name: str = Field(description="Tool function name to call")
    args: dict = Field(default_factory=dict, description="Arguments to pass to the tool")


_core_process_tool_result = None

# Tools that generate citation sources
# NOTE: Update this set when new citation-capable tools are added to Open WebUI.
CITATION_TOOLS = {
    "search_web",
    "view_file",
    "view_knowledge_file",
    "query_knowledge_files",
    "fetch_url",
}

# Terminal tool names that should emit UI refresh/display events.
TERMINAL_EVENT_TOOLS = {
    "display_file",
    "write_file",
    "replace_file_content",
    "run_command",
}


# ============================================================================
# Helper functions (outside class - AI cannot invoke these)
# ============================================================================


async def maybe_await(value):
    if hasattr(value, "__await__"):
        return await value
    return value


async def resolve_terminal_id_from_request_and_metadata(
    *,
    request: Optional[Request],
    metadata: Optional[dict],
    debug: bool = False,
) -> str:
    """Resolve terminal_id from request.body() first, then metadata."""

    def normalize_terminal_id(value: Any) -> str:
        if not isinstance(value, str):
            return ""
        return value.strip()

    metadata_terminal_id = ""
    if isinstance(metadata, dict):
        metadata_terminal_id = normalize_terminal_id(metadata.get("terminal_id"))

    request_terminal_id = ""
    if request is not None:
        request_body = getattr(request, "body", None)
        if callable(request_body):
            try:
                raw_body = await request_body()
                if raw_body:
                    body = json.loads(raw_body)
                    if isinstance(body, dict):
                        request_terminal_id = normalize_terminal_id(body.get("terminal_id"))
                        if not request_terminal_id:
                            nested_metadata = body.get("metadata")
                            if isinstance(nested_metadata, dict):
                                request_terminal_id = normalize_terminal_id(
                                    nested_metadata.get("terminal_id")
                                )
            except Exception:
                request_terminal_id = ""

    if request_terminal_id:
        if debug and metadata_terminal_id and metadata_terminal_id != request_terminal_id:
            log.warning(
                "[ParallelTools] terminal_id mismatch between request body and metadata; "
                "using request body terminal_id"
            )
        return request_terminal_id

    return metadata_terminal_id


def normalize_direct_tool_servers(value: Any) -> List[dict]:
    """Normalize direct tool server payload into a list of dict copies."""
    if not isinstance(value, list):
        return []
    normalized = []
    for item in value:
        if isinstance(item, dict):
            normalized.append(dict(item))
    return normalized


async def resolve_direct_tool_servers_from_request_and_metadata(
    *,
    request: Optional[Request],
    metadata: Optional[dict],
    debug: bool = False,
) -> List[dict]:
    """Resolve direct tool servers from request.body() first, then metadata."""
    metadata_servers = normalize_direct_tool_servers(
        (metadata or {}).get("tool_servers") if isinstance(metadata, dict) else None
    )

    request_servers: List[dict] = []
    if request is not None:
        request_body = getattr(request, "body", None)
        if callable(request_body):
            try:
                raw_body = await request_body()
                if raw_body:
                    body = json.loads(raw_body)
                    if isinstance(body, dict):
                        request_servers = normalize_direct_tool_servers(body.get("tool_servers"))
                        if not request_servers:
                            nested_metadata = body.get("metadata")
                            if isinstance(nested_metadata, dict):
                                request_servers = normalize_direct_tool_servers(
                                    nested_metadata.get("tool_servers")
                                )
            except Exception:
                request_servers = []

    if request_servers:
        if debug and metadata_servers and len(metadata_servers) != len(request_servers):
            log.warning(
                "[ParallelTools] tool_servers mismatch between request body and metadata; "
                "using request body tool_servers"
            )
        return request_servers

    return metadata_servers


def build_direct_tools_dict(*, tool_servers: List[dict]) -> dict:
    """Build direct tool entries compatible with Open WebUI middleware."""
    direct_tools = {}
    for server in tool_servers:
        if not isinstance(server, dict):
            continue
        specs = server.get("specs", [])
        if not isinstance(specs, list) or not specs:
            continue

        server_payload = {k: v for k, v in server.items() if k != "specs"}
        for spec in specs:
            if not isinstance(spec, dict):
                continue
            name = spec.get("name")
            if not isinstance(name, str) or not name:
                continue
            direct_tools[name] = {
                "spec": spec,
                "direct": True,
                "server": server_payload,
                "type": "direct",
            }
    return direct_tools


async def execute_direct_tool_call(
    *,
    tool_name: str,
    tool_args: dict,
    tool: dict,
    extra_params: dict,
) -> Any:
    """Execute direct tools through __event_call__ like core middleware."""
    event_call = extra_params.get("__event_call__")
    if not callable(event_call):
        raise RuntimeError("Direct tool execution requires __event_call__ context")

    metadata = extra_params.get("__metadata__")
    session_id = metadata.get("session_id") if isinstance(metadata, dict) else None
    return await event_call(
        {
            "type": "execute:tool",
            "data": {
                "id": str(uuid.uuid4()),
                "name": tool_name,
                "params": tool_args,
                "server": tool.get("server", {}),
                "session_id": session_id,
            },
        }
    )


def normalize_terminal_tools_result(*, terminal_tools_result: Any, extra_params: Optional[dict]) -> dict:
    """Normalize get_terminal_tools() return value across Open WebUI versions."""
    terminal_system_prompt = None
    terminal_tools = terminal_tools_result

    if (
        isinstance(terminal_tools_result, tuple)
        and len(terminal_tools_result) == 2
        and isinstance(terminal_tools_result[0], dict)
    ):
        terminal_tools = terminal_tools_result[0]
        if isinstance(terminal_tools_result[1], str):
            stripped_prompt = terminal_tools_result[1].strip()
            if stripped_prompt:
                terminal_system_prompt = stripped_prompt

    if isinstance(extra_params, dict):
        if terminal_system_prompt:
            extra_params["__terminal_system_prompt__"] = terminal_system_prompt
        else:
            extra_params.pop("__terminal_system_prompt__", None)

    if isinstance(terminal_tools, dict):
        return terminal_tools
    return {}


def _normalize_user(user: Any) -> Any:
    """Convert raw __user__ dict payloads into UserModel when needed."""
    if user is None or hasattr(user, "id"):
        return user
    if isinstance(user, dict):
        try:
            from open_webui.models.users import UserModel

            return UserModel(**user)
        except Exception:
            from types import SimpleNamespace

            return SimpleNamespace(**user)
    return user


async def process_tool_result(
    *,
    tool_function_name: str = "tool",
    tool_type: str,
    tool_result: Any,
    direct_tool: bool = False,
    request: Optional[Request] = None,
    metadata: Optional[dict] = None,
    user: Any = None,
) -> tuple[Any, list, list]:
    """Process tool result into (payload, files, embeds) using core when available."""
    global _core_process_tool_result
    if _core_process_tool_result is None:
        try:
            from open_webui.utils.middleware import process_tool_result as fn

            if fn is not None:
                _core_process_tool_result = fn
        except ImportError:
            pass
    if _core_process_tool_result is not None:
        return await maybe_await(_core_process_tool_result(
            request,
            tool_function_name,
            tool_result,
            tool_type,
            direct_tool=direct_tool,
            metadata=metadata if isinstance(metadata, dict) else {},
            user=_normalize_user(user),
        ))
    # Fallback for Open WebUI < 0.8.x
    if isinstance(tool_result, tuple):
        tool_result = tool_result[0] if tool_result else ""
    elif direct_tool and isinstance(tool_result, list) and len(tool_result) == 2:
        tool_result = tool_result[0]
    if isinstance(tool_result, (dict, list)):
        tool_result = json.dumps(tool_result, indent=2, ensure_ascii=False)
    elif tool_result is not None and not isinstance(tool_result, str):
        tool_result = str(tool_result)
    return tool_result, [], []


async def execute_single_tool(
    tool_name: str,
    tool_args: dict,
    tools_dict: dict,
    extra_params: dict,
    event_emitter: Optional[Callable] = None,
) -> dict:
    """Execute a single tool and return the result.

    Args:
        tool_name: Name of the tool to execute
        tool_args: Arguments to pass to the tool
        tools_dict: Dict of available tools {name: {callable, spec, ...}}
        extra_params: Extra parameters to pass to tool functions
        event_emitter: Optional event emitter for status updates

    Returns:
        Dict with tool_name and result (any JSON-serializable value)
    """
    # Strip "functions." prefix if present (OpenAI models sometimes add this)
    if tool_name.startswith("functions."):
        tool_name = tool_name[len("functions.") :]

    if tool_name not in tools_dict:
        return {
            "tool_name": tool_name,
            "result": f"Error: Tool '{tool_name}' not found. Check the tool name.",
        }

    tool = tools_dict[tool_name]
    spec = tool.get("spec", {})

    try:
        # Filter to allowed parameters
        allowed_params = spec.get("parameters", {}).get("properties", {}).keys()
        filtered_args = {k: v for k, v in tool_args.items() if k in allowed_params}
        direct_tool = bool(tool.get("direct", False))
        tool_result_files: list[dict] = []
        tool_result_embeds: list[Any] = []

        if direct_tool:
            result = await execute_direct_tool_call(
                tool_name=tool_name,
                tool_args=filtered_args,
                tool=tool,
                extra_params=extra_params,
            )
        else:
            tool_function = tool["callable"]

            # Update function with current messages/files context
            from open_webui.utils.tools import get_updated_tool_function

            tool_function = await maybe_await(get_updated_tool_function(
                function=tool_function,
                extra_params={
                    "__messages__": extra_params.get("__messages__", []),
                    "__files__": extra_params.get("__files__", []),
                },
            ))

            result = await tool_function(**filtered_args)

        # Handle OpenAPI/external/direct tool results that return (data, headers)
        tool_type = tool.get("type", "")
        result, tool_result_files, tool_result_embeds = await process_tool_result(
            tool_function_name=tool_name,
            tool_type=tool_type,
            tool_result=result,
            direct_tool=direct_tool,
            request=extra_params.get("__request__"),
            metadata=extra_params.get("__metadata__"),
            user=extra_params.get("__user__"),
        )

        # Emit terminal:* events for display/refresh behavior in UI
        await emit_terminal_tool_event(
            tool_name=tool_name,
            tool_args=filtered_args,
            tool_result=result,
            event_emitter=event_emitter,
        )
        defer_artifact_events = bool(extra_params.get("__defer_artifact_events__", False))
        if event_emitter and tool_result_files and not defer_artifact_events:
            await event_emitter({"type": "files", "data": {"files": tool_result_files}})
        if event_emitter and tool_result_embeds and not defer_artifact_events:
            await event_emitter({"type": "embeds", "data": {"embeds": tool_result_embeds}})

        # Try to parse JSON string results to avoid double-encoding
        if isinstance(result, str):
            try:
                result = json.loads(result)
            except json.JSONDecodeError:
                pass  # Keep as string if not valid JSON

        # Extract and emit citation sources for tools that generate them
        if event_emitter and result and tool_name in CITATION_TOOLS:
            # For citation extraction, we need a string representation
            result_str = (
                result
                if isinstance(result, str)
                else json.dumps(result, ensure_ascii=False, default=str)
            )
            try:
                from open_webui.utils.middleware import (
                    get_citation_source_from_tool_result,
                )

                tool_id = tools_dict.get(tool_name, {}).get("tool_id", "")
                citation_sources = get_citation_source_from_tool_result(
                    tool_name=tool_name,
                    tool_params=filtered_args,
                    tool_result=result_str,
                    tool_id=tool_id,
                )
                for source in citation_sources:
                    await event_emitter({"type": "source", "data": source})
            except Exception as e:
                log.warning(f"Error extracting citation sources from {tool_name}: {e}")

        return {
            "tool_name": tool_name,
            "result": result,
            **({"files": tool_result_files} if tool_result_files else {}),
            **(
                {
                    "embeds": tool_result_embeds
                }
                if tool_result_embeds and (not event_emitter or defer_artifact_events)
                else {}
            ),
        }

    except Exception as e:
        log.exception(f"Error executing tool {tool_name}: {e}")
        return {
            "tool_name": tool_name,
            "result": f"Error: {e}",
        }


async def emit_terminal_tool_event(
    *,
    tool_name: str,
    tool_args: dict,
    tool_result: Any,
    event_emitter: Optional[Callable],
) -> None:
    """Emit terminal:* UI events for Open Terminal tool results."""
    if not event_emitter or tool_name not in TERMINAL_EVENT_TOOLS:
        return

    if tool_name == "display_file":
        path = tool_args.get("path", "") if isinstance(tool_args, dict) else ""
        if not isinstance(path, str) or not path:
            return
        parsed = tool_result
        if isinstance(parsed, str):
            try:
                parsed = json.loads(parsed)
            except Exception:
                parsed = tool_result
        if isinstance(parsed, dict) and parsed.get("exists") is False:
            return
        event = {"type": "terminal:display_file", "data": {"path": path}}
    elif tool_name in {"write_file", "replace_file_content"}:
        path = tool_args.get("path", "") if isinstance(tool_args, dict) else ""
        if not isinstance(path, str) or not path:
            return
        event = {"type": f"terminal:{tool_name}", "data": {"path": path}}
    elif tool_name == "run_command":
        event = {"type": "terminal:run_command", "data": {}}
    else:
        return

    try:
        await event_emitter(event)
    except Exception as e:
        log.warning(f"Error emitting terminal event for {tool_name}: {e}")


