class Tools:
    """Parallel tool execution for independent operations."""

    class Valves(BaseModel):
        AVAILABLE_TOOL_IDS: str = Field(
            default="",
            description="Comma-separated list of tool IDs available for parallel execution. Leave empty to use all tools.",
        )
        EXCLUDED_TOOL_IDS: str = Field(
            default="",
            description="Comma-separated list of tool IDs to exclude from parallel execution.",
        )
        ENABLE_TERMINAL_TOOLS: bool = Field(
            default=True,
            description=(
                "Enable Open Terminal tools when terminal_id is available in chat metadata "
                "(e.g., run_command, list_files, read_file, write_file, display_file)."
            ),
        )
        DEBUG: bool = Field(
            default=False,
            description="Enable debug logging.",
        )
        pass

    def __init__(self):
        self.valves = self.Valves()

    async def run_tools_parallel(
        self,
        tool_calls: list[ToolCallItem],
        __user__: dict = None,
        __request__: Request = None,
        __model__: dict = None,
        __metadata__: dict = None,
        __id__: str = None,
        __event_emitter__: Callable[[dict], Any] = None,
        __event_call__: Callable[[dict], Any] = None,
        __chat_id__: str = None,
        __message_id__: str = None,
        __oauth_token__: Optional[dict] = None,
        __messages__: Optional[List[dict]] = None,
    ) -> str:
        """
        Execute multiple independent tool calls in parallel.

        IMPORTANT - Read carefully:
        Open WebUI executes tool calls sequentially by default. When you call multiple
        tools separately, each one waits for the previous to complete, causing significant
        delays. Even if you use multi_tool_use.parallel or return multiple tool calls at
        once, Open WebUI will process them one by one - NOT in parallel.

        The user has enabled this tool specifically to solve this problem. Use this tool
        when you need to call 2+ independent tools. Batch them together in a single call
        to run concurrently. This dramatically reduces wait time.

        Example scenario:
        - BAD: Call search_web("Python"), wait, call search_web("FastAPI"), wait → slow
        - BAD: Use multi_tool_use.parallel → still sequential in Open WebUI
        - GOOD: Call run_tools_parallel with both searches → true parallel execution

        :param tool_calls: List of tool calls. Each item has "name" (tool name) and "args" (arguments dict). Example: [{"name": "search_web", "args": {"query": "Python"}}]
        :return: JSON object with results for each tool call
        """
        if __request__ is None:
            return json.dumps({"error": "Request context not available."})

        if __user__ is None:
            return json.dumps({"error": "User context not available."})

        # Convert ToolCallItem instances to dicts for uniform processing
        if isinstance(tool_calls, list):
            calls = [
                c.model_dump() if isinstance(c, ToolCallItem) else c
                for c in tool_calls
            ]
        elif isinstance(tool_calls, str):
            try:
                calls = ast.literal_eval(tool_calls)
            except Exception:
                try:
                    calls = json.loads(tool_calls)
                except Exception as e:
                    return json.dumps(
                        {
                            "error": f"Failed to parse tool_calls: {e}",
                            "expected_format": '[{"name": "tool_name", "arguments": {"arg1": "value1"}}]',
                        }
                    )
        else:
            return json.dumps(
                {
                    "error": f"tool_calls must be a list or JSON string, got {type(tool_calls).__name__}",
                }
            )

        if not isinstance(calls, list):
            return json.dumps(
                {
                    "error": "tool_calls must be a JSON array",
                    "expected_format": '[{"name": "tool_name", "arguments": {"arg1": "value1"}}]',
                }
            )

        if not calls:
            return json.dumps({"error": "tool_calls array is empty"})

        # Validate each call
        for i, call in enumerate(calls):
            # Fallback: parse JSON strings (some LLMs pass stringified objects
            # when the schema advertises items as strings).
            if isinstance(call, str):
                try:
                    call = json.loads(call)
                    calls[i] = call
                except (json.JSONDecodeError, TypeError):
                    return json.dumps(
                        {"error": f"tool_calls[{i}] must be an object, got unparseable string"},
                        ensure_ascii=False,
                    )
            if not isinstance(call, dict):
                return json.dumps({"error": f"tool_calls[{i}] must be an object"})
            if "name" not in call:
                return json.dumps({"error": f"tool_calls[{i}] missing 'name' field"})
            # Accept "args", "arguments", and "parameters" keys
            if "args" in call:
                calls[i]["arguments"] = call["args"]
            elif "arguments" not in call:
                if "parameters" in call:
                    calls[i]["arguments"] = call["parameters"]
                else:
                    calls[i]["arguments"] = {}

            # Parse arguments if it's a JSON string
            if isinstance(calls[i].get("arguments"), str):
                try:
                    calls[i]["arguments"] = json.loads(calls[i]["arguments"])
                except json.JSONDecodeError:
                    pass  # Keep as-is if not valid JSON

            # Ensure arguments is a dict (handle null/None and other invalid types)
            if not isinstance(calls[i].get("arguments"), dict):
                calls[i]["arguments"] = {}

        # Import here to avoid issues when not running in Open WebUI
        from open_webui.models.users import UserModel
        from open_webui.utils.tools import get_tools

        user = UserModel(**__user__)
        __metadata__ = __metadata__ or {}

        terminal_id = await resolve_terminal_id_from_request_and_metadata(
            request=__request__,
            metadata=__metadata__,
            debug=self.valves.DEBUG,
        )
        if terminal_id:
            __metadata__["terminal_id"] = terminal_id

        direct_tool_servers = await resolve_direct_tool_servers_from_request_and_metadata(
            request=__request__,
            metadata=__metadata__,
            debug=self.valves.DEBUG,
        )
        if direct_tool_servers:
            __metadata__["tool_servers"] = direct_tool_servers

        extra_params = {
            "__user__": __user__,
            "__event_emitter__": __event_emitter__,
            "__event_call__": __event_call__,
            "__request__": __request__,
            "__model__": __model__,
            "__metadata__": __metadata__,
            "__chat_id__": __chat_id__,
            "__message_id__": __message_id__,
            "__oauth_token__": __oauth_token__,
            "__files__": __metadata__.get("files", []) if __metadata__ else [],
        }

        # Determine which tools to use
        available_tool_ids = []
        if __metadata__ and __metadata__.get("tool_ids"):
            available_tool_ids = list(__metadata__.get("tool_ids", []))

        if self.valves.AVAILABLE_TOOL_IDS.strip():
            tool_id_list = [
                tid.strip()
                for tid in self.valves.AVAILABLE_TOOL_IDS.split(",")
                if tid.strip()
            ]
        else:
            tool_id_list = available_tool_ids

        # Apply exclusions
        excluded = set()
        if self.valves.EXCLUDED_TOOL_IDS.strip():
            excluded = {
                tid.strip()
                for tid in self.valves.EXCLUDED_TOOL_IDS.split(",")
                if tid.strip()
            }

        # Exclude this tool itself
        if __id__:
            excluded.add(__id__)

        tool_id_list = [tid for tid in tool_id_list if tid not in excluded]

        # Filter out builtin: prefixed IDs
        regular_tool_ids = [
            tid for tid in tool_id_list if not tid.startswith("builtin:")
        ]

        if self.valves.DEBUG:
            log.info(f"[ParallelTools] Tool IDs: {regular_tool_ids}")

        # Load tools
        tools_dict = {}
        if regular_tool_ids:
            try:
                tools_dict = await get_tools(
                    request=__request__,
                    tool_ids=regular_tool_ids,
                    user=user,
                    extra_params=extra_params,
                )

                if self.valves.DEBUG:
                    log.info(f"[ParallelTools] Loaded {len(tools_dict)} tools")

            except Exception as e:
                log.exception(f"Error loading tools: {e}")
                return json.dumps({"error": f"Failed to load tools: {e}"})

        # Load terminal tools
        if terminal_id and self.valves.ENABLE_TERMINAL_TOOLS:
            try:
                from open_webui.utils.tools import get_terminal_tools

                terminal_tools_result = await get_terminal_tools(
                    request=__request__,
                    terminal_id=terminal_id,
                    user=user,
                    extra_params=extra_params,
                )
                terminal_tools = normalize_terminal_tools_result(
                    terminal_tools_result=terminal_tools_result,
                    extra_params=extra_params,
                )
                if terminal_tools:
                    tools_dict = {**tools_dict, **terminal_tools}
                    if self.valves.DEBUG:
                        log.info(
                            f"[ParallelTools] Loaded {len(terminal_tools)} terminal tools for terminal_id={terminal_id}"
                        )
            except Exception as e:
                log.exception(f"Error loading terminal tools: {e}")

        # Load direct tools from metadata.tool_servers
        if direct_tool_servers:
            try:
                direct_tools = build_direct_tools_dict(tool_servers=direct_tool_servers)
                if direct_tools:
                    tools_dict = {**tools_dict, **direct_tools}
                    if self.valves.DEBUG:
                        log.info(f"[ParallelTools] Loaded {len(direct_tools)} direct tools")
            except Exception as e:
                log.exception(f"Error loading direct tools: {e}")

        # Load builtin tools
        try:
            from open_webui.utils.tools import get_builtin_tools

            features = __metadata__.get("features", {}) if __metadata__ else {}
            model = __model__ or {}

            builtin_extra_params = {
                "__user__": __user__,
                "__event_emitter__": __event_emitter__,
                "__event_call__": __event_call__,
                "__metadata__": __metadata__,
                "__chat_id__": __chat_id__,
                "__message_id__": __message_id__,
                "__oauth_token__": __oauth_token__,
            }

            all_builtin_tools = await maybe_await(get_builtin_tools(
                request=__request__,
                extra_params=builtin_extra_params,
                features=features,
                model=model,
            ))

            # Add builtin tools (regular tools take priority)
            for name, tool_dict in all_builtin_tools.items():
                if name not in tools_dict:
                    tools_dict[name] = tool_dict

            if self.valves.DEBUG:
                log.info(f"[ParallelTools] Total tools available: {len(tools_dict)}")

        except Exception as e:
            log.exception(f"Error loading builtin tools: {e}")

        # Prepare extra params for execution
        exec_extra_params = {
            "__user__": __user__,
            "__request__": __request__,
            "__model__": __model__,
            "__metadata__": __metadata__,
            "__event_emitter__": __event_emitter__,
            "__event_call__": __event_call__,
            "__chat_id__": __chat_id__,
            "__message_id__": __message_id__,
            "__oauth_token__": __oauth_token__,
            "__messages__": __messages__ or [],
            "__files__": __metadata__.get("files", []) if __metadata__ else [],
            "__defer_artifact_events__": True,
        }

        # Execute all tools in parallel
        tasks = [
            execute_single_tool(
                tool_name=call.get("name", ""),
                tool_args=call.get("arguments", {}),
                tools_dict=tools_dict,
                extra_params=exec_extra_params,
                event_emitter=__event_emitter__,
            )
            for call in calls
        ]

        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Process results
        processed_results = []
        aggregated_files = []
        aggregated_embeds = []
        for i, result in enumerate(results):
            if isinstance(result, Exception):
                processed_results.append(
                    {
                        "tool_name": calls[i].get("name", "unknown"),
                        "result": f"Error: {result}",
                    }
                )
            else:
                if isinstance(result, dict):
                    files = result.get("files", [])
                    embeds = result.get("embeds", [])
                    if isinstance(files, list):
                        aggregated_files.extend(files)
                        if __event_emitter__:
                            result = {k: v for k, v in result.items() if k != "files"}
                    if isinstance(embeds, list):
                        aggregated_embeds.extend(embeds)
                        if __event_emitter__:
                            result = {k: v for k, v in result.items() if k != "embeds"}
                processed_results.append(result)

        if __event_emitter__ and aggregated_files:
            await __event_emitter__({"type": "files", "data": {"files": aggregated_files}})
        if __event_emitter__ and aggregated_embeds:
            await __event_emitter__({"type": "embeds", "data": {"embeds": aggregated_embeds}})

        return json.dumps(
            {"results": processed_results},
            ensure_ascii=False,
        )

"""
title: Repository Tree Analyzer
description: Analyze a pasted repository tree or file list without server-side filesystem reads.
version: 1.0.0
license: MIT
security: Uses only text supplied by the user. It does not open paths, read files, call networks or run commands.
"""

from __future__ import annotations

import re
from collections import Counter
from typing import Any, List

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover
    class BaseModel:
        pass

    def Field(default: Any = None, description: str = "") -> Any:
        return default


class Tools:
    """OpenWebUI toolkit for pasted repository tree analysis."""

    class Valves(BaseModel):
        max_input_chars: int = Field(120000, description="Maximum pasted tree length.")

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def analyze_tree(self, tree_text: str, __event_emitter__: Any = None) -> str:
        """
        Analyze a pasted file tree and suggest missing repository hygiene files.
        :param tree_text: Pasted output from a file tree, rg --files or similar.
        """
        if len(tree_text) > int(self.valves.max_input_chars):
            return "Fehler: Eingabe ist zu groß."
        await self._emit(__event_emitter__, "Analysiere Repository-Baum", False)
        paths = [self._clean(line) for line in tree_text.splitlines() if self._clean(line)]
        suffixes = Counter(self._suffix(path) for path in paths if self._suffix(path))
        names = {path.lower().replace("\\", "/").split("/")[-1] for path in paths}
        dirs = {path.lower().replace("\\", "/").split("/")[0] for path in paths if "/" in path.replace("\\", "/")}
        gaps: List[str] = []
        for required in ["readme.md", "license", "security.md", ".gitignore"]:
            if required not in names:
                gaps.append(f"`{required}` nicht erkannt.")
        if not any(name.startswith("test_") or name in {"tests", "pytest.ini"} for name in names | dirs):
            gaps.append("Keine klare Teststruktur erkannt.")
        if not any("openwebui" in path.lower() and "tools" in path.lower() for path in paths):
            gaps.append("Keine offensichtliche OpenWebUI-Toolstruktur erkannt.")
        await self._emit(__event_emitter__, "Repository-Baum analysiert", True)
        lines = [
            "# Repository-Baum-Analyse",
            f"- Einträge: {len(paths)}",
            f"- Top-Level-Ordner: {', '.join(sorted(dirs)[:20]) if dirs else 'keine erkannt'}",
            "",
            "## Häufige Dateitypen",
        ]
        lines.extend(f"- `.{suffix}`: {count}" for suffix, count in suffixes.most_common(12))
        lines.extend(["", "## Lücken", *(f"- {gap}" for gap in gaps or ["Keine offensichtlichen Hygiene-Lücken erkannt."])])
        lines.extend(["", "## Empfohlene OpenWebUI-Erweiterungsstruktur", "- `Tools/openwebui_ext/tools/` für importierbare `.py`-Tools", "- `Tools/openwebui_ext/skills/` für importierbare `.md`-Skills", "- `Tools/openwebui_ext/docs/` für Import-, Sicherheits- und Betriebshinweise", "- `Artefakte/` für offline erzeugte Ergebnisse", "- `scripts/validate_openwebui_extensions.py` für lokale Prüfung"])
        return "\n".join(lines)

    def _clean(self, line: str) -> str:
        return re.sub(r"^[\s|`+\\-]+", "", line).strip()

    def _suffix(self, path: str) -> str:
        name = path.replace("\\", "/").rsplit("/", 1)[-1]
        if "." not in name or name.startswith("."):
            return ""
        return name.rsplit(".", 1)[-1].lower()

    async def _emit(self, emitter: Any, description: str, done: bool) -> None:
        if emitter:
            await emitter({"type": "status", "data": {"description": description, "done": done}})

"""
title: Safe HTTP Fetcher
description: Bounded HTTP GET and HEAD inspection for public URLs with SSRF protections.
version: 1.0.0
license: MIT
offline: false
security: Only http/https URLs are allowed. Private, loopback, link-local and multicast hosts are blocked by default. No cookies, secrets, POST requests, shell commands or filesystem access are used.
"""

from __future__ import annotations

import html
import ipaddress
import re
import socket
import urllib.error
import urllib.parse
import urllib.request
from typing import Any, Dict, List, Optional, Tuple

try:
    from pydantic import BaseModel, Field
except Exception:  # pragma: no cover - OpenWebUI normally provides pydantic
    class BaseModel:
        pass

    def Field(default: Any = None, description: str = "") -> Any:
        return default


SENSITIVE_HEADERS = {"authorization", "cookie", "set-cookie", "proxy-authorization", "x-api-key"}


class _CheckedRedirect(urllib.request.HTTPRedirectHandler):
    def __init__(self, owner: "Tools") -> None:
        self.owner = owner
        self.redirect_count = 0

    def redirect_request(self, req: urllib.request.Request, fp: Any, code: int, msg: str, headers: Any, newurl: str) -> urllib.request.Request:
        self.redirect_count += 1
        if self.redirect_count > self.owner.valves.max_redirects:
            raise urllib.error.HTTPError(newurl, code, "redirect limit reached", headers, fp)
        self.owner._validate_url(newurl)
        return urllib.request.HTTPRedirectHandler.redirect_request(self, req, fp, code, msg, headers, newurl)


class Tools:
    """OpenWebUI toolkit for safe public HTTP inspection."""

    citation = False

    class Valves(BaseModel):
        timeout_seconds: int = Field(10, description="Network timeout per request.")
        max_response_bytes: int = Field(65536, description="Maximum bytes read from a response body.")
        max_redirects: int = Field(3, description="Maximum followed redirects.")
        allow_private_networks: bool = Field(False, description="Allow private or local IP ranges. Keep disabled for normal use.")
        user_agent: str = Field("OpenWebUI-SafeHTTPFetcher/1.0", description="User-Agent sent to public servers.")

    def __init__(self) -> None:
        self.valves = self.Valves()

    async def fetch_url(self, url: str, method: str = "GET", extract_links: bool = True, __event_emitter__: Any = None) -> str:
        """
        Fetch a public URL with GET or HEAD and return status, safe headers and a truncated body summary.
        :param url: Public http or https URL.
        :param method: GET or HEAD.
        :param extract_links: Extract title and links from HTML bodies when true.
        """
        method = method.upper().strip()
        if method not in {"GET", "HEAD"}:
            return "Fehler: Nur GET und HEAD sind erlaubt."
        try:
            clean_url = self._validate_url(url)
        except ValueError as exc:
            return f"Fehler: {exc}"

        await self._emit(__event_emitter__, "Rufe öffentliche URL ab", False)
        request = urllib.request.Request(clean_url, method=method, headers={"User-Agent": self.valves.user_agent, "Accept": "text/html,application/json,text/plain,*/*;q=0.8"})
        opener = urllib.request.build_opener(_CheckedRedirect(self))
        try:
            with opener.open(request, timeout=max(1, int(self.valves.timeout_seconds))) as response:
                status = getattr(response, "status", response.getcode())
                final_url = response.geturl()
                headers = self._safe_headers(dict(response.headers.items()))
                raw = b"" if method == "HEAD" else response.read(max(0, int(self.valves.max_response_bytes)) + 1)
        except urllib.error.HTTPError as exc:
            raw = exc.read(min(max(0, int(self.valves.max_response_bytes)), 8192)) if method != "HEAD" else b""
            status = exc.code
            final_url = exc.url
            headers = self._safe_headers(dict(exc.headers.items()) if exc.headers else {})
        except Exception as exc:
            await self._emit(__event_emitter__, "HTTP-Abruf fehlgeschlagen", True)
            return f"Fehler: HTTP-Abruf fehlgeschlagen: {type(exc).__name__}: {self._redact(str(exc))}"

        truncated = len(raw) > int(self.valves.max_response_bytes)
        raw = raw[: int(self.valves.max_response_bytes)]
        text = self._decode(raw, headers.get("content-type", ""))
        await self._emit(__event_emitter__, "HTTP-Abruf abgeschlossen", True)
        if __event_emitter__:
            await __event_emitter__({"type": "citation", "data": {"source": {"name": final_url, "url": final_url}, "document": [text[:1000]], "metadata": [{"source": final_url}]}})

        parts = [
            "# HTTP-Ergebnis",
            f"- URL: `{self._redact(final_url)}`",
            f"- Status: `{status}`",
            f"- Gekürzt: `{truncated}`",
            "",
            "## Header",
            self._format_headers(headers),
        ]
        if method == "GET":
            title, links = self._extract_html(text)
            if title or (extract_links and links):
                parts.extend(["", "## HTML-Auswertung"])
                if title:
                    parts.append(f"- Titel: {title}")
                if extract_links and links:
                    parts.append("- Links:")
                    parts.extend(f"  - {link}" for link in links[:20])
            parts.extend(["", "## Inhalt", "```text", self._redact(text[:4000]), "```"])
        return "\n".join(parts)

    async def check_status(self, url: str, __event_emitter__: Any = None) -> str:
        """
        Check a public URL via HEAD and return status and safe headers.
        :param url: Public http or https URL.
        """
        return await self.fetch_url(url=url, method="HEAD", extract_links=False, __event_emitter__=__event_emitter__)

    def _validate_url(self, url: str) -> str:
        if len(url) > 2048:
            raise ValueError("URL ist zu lang.")
        parsed = urllib.parse.urlparse(url.strip())
        if parsed.scheme not in {"http", "https"}:
            raise ValueError("Nur http und https sind erlaubt.")
        if not parsed.hostname:
            raise ValueError("URL enthält keinen Host.")
        host = parsed.hostname.rstrip(".")
        if not self.valves.allow_private_networks:
            infos = socket.getaddrinfo(host, parsed.port or (443 if parsed.scheme == "https" else 80), proto=socket.IPPROTO_TCP)
            for info in infos:
                ip = ipaddress.ip_address(info[4][0])
                if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_reserved or ip.is_unspecified:
                    raise ValueError("Private, lokale oder reservierte Netzwerkziele sind blockiert.")
        return urllib.parse.urlunparse(parsed._replace(fragment=""))

    def _safe_headers(self, headers: Dict[str, str]) -> Dict[str, str]:
        return {k.lower(): ("[REDACTED]" if k.lower() in SENSITIVE_HEADERS else self._redact(str(v))[:500]) for k, v in headers.items()}

    def _format_headers(self, headers: Dict[str, str]) -> str:
        if not headers:
            return "_Keine Header verfügbar._"
        return "\n".join(f"- `{k}`: `{v}`" for k, v in sorted(headers.items()))

    def _decode(self, raw: bytes, content_type: str) -> str:
        charset = "utf-8"
        match = re.search(r"charset=([\w.-]+)", content_type, re.I)
        if match:
            charset = match.group(1)
        return raw.decode(charset, errors="replace")

    def _extract_html(self, text: str) -> Tuple[str, List[str]]:
        title_match = re.search(r"<title[^>]*>(.*?)</title>", text, re.I | re.S)
        title = html.unescape(re.sub(r"\s+", " ", title_match.group(1)).strip()) if title_match else ""
        links = []
        for match in re.finditer(r"<a\s+[^>]*href=[\"']([^\"']+)[\"']", text, re.I):
            href = html.unescape(match.group(1)).strip()
            if href.startswith(("http://", "https://")):
                links.append(self._redact(href)[:300])
        return title[:300], links

    def _redact(self, value: str) -> str:
        value = re.sub(r"(?i)(token|api[_-]?key|password|secret)=([^&\s]+)", r"\1=[REDACTED]", value)
        value = re.sub(r"(?i)(bearer\s+)[a-z0-9._~+/=-]+", r"\1[REDACTED]", value)
        return value

    async def _emit(self, emitter: Any, description: str, done: bool) -> None:
        if emitter:
            await emitter({"type": "status", "data": {"description": description, "done": done}})

